import{_ as s,a0 as i,w as r,s as p,ao as d,I as a,x as n,a1 as e,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse(`{"title":"魅族 Pro 5 Ubuntu 版即将发布 | LCTT x X-CMD","titleTemplate":false,"description":"魅族 Pro 5 Ubuntu 版即将发布 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"魅族 Pro 5 Ubuntu 版即将发布 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"魅族 Pro 5 Ubuntu 版即将发布 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast","title":"魅族 Pro 5 Ubuntu 版即将发布","tag":"201602","desc":""},"relativePath":"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast.md","filePath":"[post].md"}`),l={name:"201602/20160218 Meizu PRO 5 Ubuntu Edition Announced and It's a Beast.md"};function b(m,t,f,P,T,C){const o=i("Link");return r(),p("div",null,[t[13]||(t[13]=d('<h1 id="魅族-pro-5-ubuntu-版即将发布" tabindex="-1">魅族 Pro 5 Ubuntu 版即将发布 <a class="header-anchor" href="#魅族-pro-5-ubuntu-版即将发布" aria-label="Permalink to “魅族 Pro 5 Ubuntu 版即将发布”">​</a></h1><p><strong>Canonical 和魅族刚刚透露魅族 Pro 5 Ubuntu 版将在 2016 世界移动大会召开期间开始预售</strong></p><p>自从上次听到魅族的消息到现在已经很久了，但是看起来 Canonical 和这个中国的硬件厂商之间的合作关系仍然存在。从表面来看，之前魅族的 MX4 Ubuntu 版只是进行了小范围的发布，所以只有很少的设备卖出去了。</p><p>我们仅仅希望魅族 Pro 5 Ubuntu 版可以提高供货量，尤其是因为它是魅族的一款相当新且还提供支持的手机。</p><p>最新的魅族 Pro 5 是第 5 个支持 Ubuntu Touch 的官方设备，2016 年我们可能会看到更多的手机甚至是平板都会预装这个操作系统。</p><h2 id="魅族-pro-5-ubuntu-版将会非常震撼" tabindex="-1">魅族 Pro 5 Ubuntu 版将会非常震撼 <a class="header-anchor" href="#魅族-pro-5-ubuntu-版将会非常震撼" aria-label="Permalink to “魅族 Pro 5 Ubuntu 版将会非常震撼”">​</a></h2><p>Canonical 宣称 Pro 5 是目前已发布了的 Ubuntu 智能手机中最强大的一个，他们说的是对的，但还有一点没有被提及，即如果不考虑平板，它也是最大的 Ubuntu Touch 设备。魅族 Pro 5 采用了一颗 Exynos 7420 8 核处理器和 5.7 英寸分辨率为 1920x1080 的 AMOLED 屏，配备第三代康宁大猩猩玻璃以及 LPDDR4 内存技术。</p><p>很多人也许会问这个新手机的系统是否可以和桌面版系统一样，现在看起来真是如此。</p><p>该公司解释说，“Canonical 一直致力于通过向各种个人设备提供一个统一的自适应平台来重塑个人计算的视觉表现。因此尽管魅族 Pro 5 缺少 MHL 输出，但它运行的是最新的代码，这些代码与新近发布的平板和其它设备一样，可提供一种接近传统桌面的体验。”</p><p>魅族 Pro 5 最初于 2015 年 9 月发布，拥有一个 2100 万像素的后置摄像头，可以拍摄 30fps 的 2160p 视频。同时它还带有一个指纹传感器和支持快速充电的 3050 mAh 的锂电池。</p><p>目前这款手机只在中国和欧洲有售，预定将从 2016 年 2 月 22 日至 25 日的世界移动大会期间开始。</p><p><img src="http://i1-news.softpedia-static.com/images/fitted/620x/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526-11.jpg" alt=""></p><hr>',13)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://news.softpedia.com/news/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526.shtml"},{default:u(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/meizu-pro-5-ubuntu-edition-announced-and-it-s-a-beast-photos-500526.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=n("作者：",-1)),e(o,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:u(()=>[...t[2]||(t[2]=[n("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),e(o,{href:"https://github.com/osk874"},{default:u(()=>[...t[3]||(t[3]=[n("osk874",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),e(o,{href:"https://github.com/Yuking-net"},{default:u(()=>[...t[4]||(t[4]=[n("Yuking",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),e(o,{href:"https://linux.cn/"},{default:u(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const g=s(l,[["render",b]]);export{x as __pageData,g as default};
